   '<div class="ds-row"><a class="ds-btn ds-btn--soft" href="#/course/course-sa-'+g+'">'+DS.t('صفحة الصف','Grade page')+'</a>'+(m.secs[1]||[]).map(function(b){return b.k==='btn'?btn([b.t,b.href],b.sec?' ds-btn--soft':''):''}).join('')+'</div></div>'+asideHTML(sts.length,false)+'</div>';
